  async readLargeJSONFile(filePath) {
    try {
      const chunks = [];
      const fileStream = fs.createReadStream(filePath, {
        encoding: "utf-8",
        highWaterMark: this.chunkSize,
      });

      fileStream.on("data", (chunk) => {
        chunks.push(chunk);
      });

      await new Promise((resolve, reject) => {
        fileStream.on("end", resolve);
        fileStream.on("error", reject);
      });

      const rawData = chunks.join("");
      const jsonData = JSON.parse(rawData);
      return jsonData;
    } catch (error) {
      console.error("Error reading file:", error.message);
      logger.error("[readLargeJSONFile] error: ", error);
      throw error;
    }
  }

  async saveLargeJsonFile(fileName, jsonData) {
    try {
      const writeStream = fs.createWriteStream(fileName, {
        flags: "w",
        encoding: "utf-8",
      });

      // Ghi cấu trúc mảng JSON
      writeStream.write("[", "utf8");

      // Ghi dữ liệu từng đoạn nhỏ
      for (let i = 0; i < jsonData.length; i++) {
        const item = jsonData[i];
        const jsonString = JSON.stringify(item);

        // Kiểm tra nếu không phải phần tử cuối cùng để thêm dấu phẩy
        if (i < jsonData.length - 1) {
          writeStream.write(`${jsonString},`, "utf8");
        } else {
          writeStream.write(`${jsonString}`, "utf8");
        }
      }

      // Đóng cấu trúc mảng JSON
      writeStream.write("]\n", "utf8");

      // Đóng luồng ghi
      writeStream.end();
    } catch (error) {
      logger.error(`[saveLargeJsonFile] ${error}`);
    }
  }
  
