  async findRelatedChildren_short(parentID) {
    try {
      let path = await this.pathString_string(false);
      let find_address_num = this.find_address_num(
        parentID,
        directory_range,
        file_range,
        "id"
      );
      let address_id = `${path}${find_address_num.path}`;
      //
      // Kiểm tra cache
      // const cacheKey = `findRelatedChildren_short_${address_id}`;
      // if (cache.has(cacheKey)) {
      //   logger.info(`Cache hit for ${cacheKey}`);
      //   return cache.get(cacheKey);
      // }
      if (!fs.existsSync(address_id)) {
        //logger.info("address_id: " + address_id);
        return [];
      }

      let data_id = await this.readLargeJSONFile(address_id);
      let result = new Set();

      if (data_id[parentID]) {
        const parentData = data_id[parentID] || {};
        let type_folder;
        let list_of_type = [];
        let address;
        let data_child;
        let parent_child;

        let is_except = false;
        // Duyệt qua tất cả các phần tử trong parentData

        if (_out_type_search.length > 0) {
          is_except = true;
        }
        for (var keyA in parentData) {
          if (parentData.hasOwnProperty(keyA)) {
            if (is_except && _out_type_search.includes(keyA)) {
            } else {
              type_folder = keyA;
              list_of_type = parentData[keyA];
              // logger.info(`list_of_type: ${list_of_type}`)

              for (const childID of list_of_type) {
                address = `${path}${this.find_address(childID, type_folder)}`;
                data_child = await this.readLargeJSONFile(address);

                parent_child = data_child[childID]
                  ? data_child[childID].id
                  : [];
                result = new Set([...result, ...data_child[childID].id]);
              }
            }
          }
        }
        type_folder = list_of_type = address = data_child = parent_child = null;
      }
      let resultArray = Array.from(result);      
      // Lưu kết quả vào cache
      // cache.set(cacheKey, result);
      // if (this.change) {
      //   logger.info(`cache.delete(cacheKey)`);
      //   cache.delete(cacheKey);
      // }
      // Giảm thiểu việc giữ tham chiếu và đặt các biến không cần thiết thành null
      path = address_id = data_id = result = null;
      // Kiểm tra sự thay đổi và làm sạch cache khi có sự thay đổi

      return resultArray;
    } catch (error) {
      logger.info("address_id: " + address_id);
      logger.error(`[findRelatedChildren_short] ${error}`);
      return -1;
    }
  }

  find_address(childID, type) {
    let rs;

    if (type == "ip") {
      rs = this.find_address_ip(childID, type);
    } else if (type == "pass") {
      rs = this.find_address_alphabet(childID, type);
    } else if (type == "new_wallet") {
      rs = this.find_address_alphabet(childID, type);
    } else if (type == "device") {
      rs = this.find_address_alphabet(childID, type);
    }
    return rs;
  }

  find_address_num(parentId, range, file_range, type_short) {
    let rs = {};
    const rangeStart = Math.floor(parentId / range) * range;
    const rangeEnd = rangeStart + range;

    const rangeStart_file = Math.floor(parentId / file_range) * file_range;
    const rangeEnd_file = rangeStart_file + file_range;
    rs.path = `${type_short}/${rangeStart}_to_${rangeEnd}/${rangeStart_file}_to_${rangeEnd_file}.json`;
    rs.folder = `${rangeStart}_to_${rangeEnd}`;
    rs.name = `${rangeStart_file}_to_${rangeEnd_file}`;
    return rs;
  }
  find_address_alphabet(parentId, type_short) {
    const startStr = parentId.charAt(0).toLowerCase();
    return `${type_short}/${startStr}.json`;
  }
  find_address_ip(parentId, type_short) {
    let rs_check = this.checkIPAddressType(parentId);
    const startStr = parentId.charAt(0).toLowerCase();
    if (rs_check == "loopback") {
      return "${type_short}/loopback";
    } else if (rs_check == "IPv4") {
      return `${type_short}/IPv4_${startStr}.json`;
    } else if (rs_check == "IPv6") {
      return `${type_short}/IPv6_${startStr}.json`;
    } else {
      return `${type_short}/Unknown.json`;
    }
  }

  removeChildren(node, nodeIdToRemove) {
    if (node.children) {
      // Lọc ra các children không có ID là nodeIdToRemove
      node.children = node.children.filter(
        (child) => child.id !== nodeIdToRemove
      );

      // Gọi đệ quy cho từng child để xóa nếu nó cũng có children
      node.children.forEach((child) => removeChildren(child, nodeIdToRemove));
    }
  }

