  checkIPAddressType(ipAddress) {
    // Kiểm tra xem địa chỉ có phải là địa chỉ loopback không
    if (
      ipAddress === "localhost" ||
      ipAddress === "127.0.0.1" ||
      ipAddress === "::1"
    ) {
      return "loopback";
    }

    // Kiểm tra xem địa chỉ có phải là địa chỉ IPv4 không
    const ipv4Regex = /^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/;
    if (ipv4Regex.test(ipAddress)) {
      return "IPv4";
    }

    // Kiểm tra xem địa chỉ có phải là địa chỉ IPv6 không
    const ipv6Regex =
      /^([0-9a-fA-F]{1,4}:){7,7}[0-9a-fA-F]{1,4}$|([0-9a-fA-F]{1,4}:){1,7}:|[0-9a-fA-F]{1,4}:([0-9a-fA-F]{1,4}:){1,6}$|([0-9a-fA-F]{1,4}:){2,7}:[0-9a-fA-F]{1,4}$|([0-9a-fA-F]{1,4}:){3,7}:([0-9a-fA-F]{1,4}:){1,4}$|([0-9a-fA-F]{1,4}:){4,7}:([0-9a-fA-F]{1,4}:){1,3}$|([0-9a-fA-F]{1,4}:){5,7}:([0-9a-fA-F]{1,4}:){1,2}$|([0-9a-fA-F]{1,4}:){6,7}:[0-9a-fA-F]{1,4}$/;
    if (ipv6Regex.test(ipAddress)) {
      return "IPv6";
    }

    // Nếu không phải IPv4, IPv6 hoặc loopback
    return "Unknown";
  }

  async readStream(filePath) {
    try {
      const chunks = [];
      const fileStream = fs.createReadStream(filePath, { encoding: "utf-8" });

      const rl = readline.createInterface({
        input: fileStream,
        crlfDelay: Infinity,
      });

      return new Promise((resolve, reject) => {
        rl.on("line", (line) => {
          chunks.push(line);
        });

        rl.on("close", () => {
          if (chunks.length > 0) {
            resolve(chunks.join(""));
          } else {
            reject(new Error("No data read from the file."));
          }
        });

        rl.on("error", (error) => {
          reject(error);
        });
      });
    } catch (error) {
      throw error;
    }
  }

  async writeStream(filePath, data) {
    return new Promise((resolve, reject) => {
      const writeStream = fs.createWriteStream(filePath, {
        flags: "w",
        encoding: "utf-8",
      });

      writeStream.write(data, async (error) => {
        if (error) {
          reject(error);
        } else {
          await this.sleep(30);
          resolve();
        }
      });

      writeStream.end();
    });
  }

